/* ======================= Wish posters ======================= */
const POSTER_TYPES={"Tyohar":"fest","Birthday":"bday","Tithi Birthday":"bday","Anniversary":"ann","Punyatithi (date)":"mem","Punyatithi (tithi)":"mem","Shraddh":"mem"};
const THEMES={
  bday:[{bg:["#ffb3c1","#ffe5d9"],ink:"#5b1a2b",acc:"#c2416b",ring:"#ffd166",deco:["#ff6b8b","#ffd166","#6bcBef","#9b5de5","#00bb7f"]},
        {bg:["#1b2a6b","#3c5bd1"],ink:"#ffffff",acc:"#ffd166",ring:"#ffd166",deco:["#ffd166","#ff8fab","#8ecae6","#ffffff","#b8f2e6"]},
        {bg:["#ff7a18","#ffb347"],ink:"#ffffff",acc:"#fff3c4",ring:"#ffffff",deco:["#ffffff","#ffe066","#ff4d6d","#7bdff2","#c77dff"]}],
  ann:[{bg:["#5a0f1e","#8c1c2f"],ink:"#fff5e6",acc:"#f4c46b",ring:"#f4c46b",deco:["#f4a300","#ff7b00","#f4c46b"]},
       {bg:["#ffd6e0","#fff1f4"],ink:"#6b1d3a",acc:"#c2416b",ring:"#c2416b",deco:["#ff8fab","#ffc2d1","#f4a300"]},
       {bg:["#0f4c5c","#1f7a8c"],ink:"#ffffff",acc:"#ffd29d",ring:"#ffd29d",deco:["#ffd29d","#ff9b85","#f4a300"]}],
  fest:[{bg:["#4a0d2e","#7a1f3d"],ink:"#fff4e0",acc:"#ffc94d",ring:"#ffc94d",deco:["#ff9f1c","#ffbf69","#e71d36","#2ec4b6","#ffc94d"]},
        {bg:["#fff3d6","#ffd9a8"],ink:"#5a2a0c",acc:"#c2410c",ring:"#c2410c",deco:["#e85d04","#f48c06","#d00000","#6a994e","#ffba08"]},
        {bg:["#0b1d51","#22356f"],ink:"#ffffff",acc:"#ffd166",ring:"#ffd166",deco:["#ffd166","#ef476f","#06d6a0","#118ab2","#ff9f1c"]}],
  mem:[{bg:["#fbf3e4","#efe2c8"],ink:"#3b2f22",acc:"#9a6b1f",ring:"#c9a253",deco:["#c9a253"]},
       {bg:["#f4f4f2","#dcdcd6"],ink:"#2e2e2e",acc:"#6b6b6b",ring:"#9a9a9a",deco:["#b0b0b0"]},
       {bg:["#20243a","#3a3f5c"],ink:"#f3eee4",acc:"#e9c46a",ring:"#e9c46a",deco:["#e9c46a"]}]
};
function rng(seed){let s=seed>>>0||1;return()=>{s^=s<<13;s^=s>>>17;s^=s<<5;return ((s>>>0)%10000)/10000}}
function hashStr(t){let h=2166136261;for(const c of t)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0}
function loadImgSrc(src){return new Promise(r=>{if(!okImg(src))return r(null);const i=new Image();i.onload=()=>r(i);i.onerror=()=>r(null);i.src=src;})}
function wrapLines(ctx,text,maxW){const words=String(text).split(/\s+/);const lines=[];let cur="";
  for(const w of words){const t=cur?cur+" "+w:w; if(ctx.measureText(t).width>maxW&&cur){lines.push(cur);cur=w}else cur=t;} if(cur)lines.push(cur); return lines;}
function fitFont(ctx,text,font,size,maxW,min=40){let s=size;do{ctx.font=font.replace("{s}",s);if(ctx.measureText(text).width<=maxW)break;s-=4}while(s>min);return s}
function circlePhoto(ctx,img,name,cx,cy,r,th,gray){
  ctx.save();ctx.beginPath();ctx.arc(cx,cy,r+14,0,Math.PI*2);ctx.fillStyle=th.ring;ctx.shadowColor="rgba(0,0,0,.25)";ctx.shadowBlur=30;ctx.fill();ctx.restore();
  ctx.save();ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.clip();
  if(img){const s=Math.min(img.width,img.height);if(gray)ctx.filter="grayscale(0.75)";ctx.drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,cx-r,cy-r,2*r,2*r);ctx.filter="none";}
  else{ctx.fillStyle="#fff";ctx.fillRect(cx-r,cy-r,2*r,2*r);ctx.fillStyle=th.acc;ctx.font=`700 ${Math.round(r*0.8)}px "Fraunces",serif`;ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText(initials(name),cx,cy+4);}
  ctx.restore();
}
function drawDiya(ctx,x,y,s,th){
  const g=ctx.createRadialGradient(x,y-60*s,5,x,y-60*s,160*s);g.addColorStop(0,"rgba(255,200,80,.55)");g.addColorStop(1,"rgba(255,200,80,0)");
  ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y-60*s,160*s,0,Math.PI*2);ctx.fill();
  ctx.fillStyle="#b5651d";ctx.beginPath();ctx.ellipse(x,y,90*s,32*s,0,0,Math.PI);ctx.fill();
  ctx.fillStyle="#d98c3f";ctx.beginPath();ctx.ellipse(x,y,90*s,16*s,0,0,Math.PI*2);ctx.fill();
  const f=ctx.createLinearGradient(x,y-110*s,x,y-10*s);f.addColorStop(0,"#fff6b0");f.addColorStop(.5,"#ffb703");f.addColorStop(1,"#fb5607");
  ctx.fillStyle=f;ctx.beginPath();ctx.moveTo(x,y-115*s);ctx.bezierCurveTo(x+34*s,y-60*s,x+26*s,y-14*s,x,y-12*s);ctx.bezierCurveTo(x-26*s,y-14*s,x-34*s,y-60*s,x,y-115*s);ctx.fill();
}
function heart(ctx,x,y,s,c){ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(x,y+s*.3);ctx.bezierCurveTo(x,y,x-s*.5,y,x-s*.5,y+s*.3);ctx.bezierCurveTo(x-s*.5,y+s*.6,x,y+s*.8,x,y+s);ctx.bezierCurveTo(x,y+s*.8,x+s*.5,y+s*.6,x+s*.5,y+s*.3);ctx.bezierCurveTo(x+s*.5,y,x,y,x,y+s*.3);ctx.fill();}
function posterInfo(e){
  if(e.type==="Tyohar"){ const f=e.fest||{name:e.name,hi:e.name,icon:e.icon}; const fam0="गुलेच्छा परिवार";
    return {kind:"fest",mb:{},h1:f.hi,h2:"की हार्दिक शुभकामनाएं",name:"",line:"",icon:f.icon,date:fmtDate(e.iso),msg:`Aapko aur aapke parivar ko ${f.name} ki dher saari shubhkamnayein. Prabhu sab par kripa banaye rakhein!`,from:`शुभेच्छु – ${fam0}`}; }
  const mb=byId(e.id)||{}; const kind=POSTER_TYPES[e.type]; const yr=+e.iso.slice(0,4);
  const sp=mb.spouse_id?byId(mb.spouse_id):null;
  const fam="गुलेच्छा परिवार"; const famM="समस्त गुलेच्छा परिवार";
  if(kind==="bday"){
    const n=mb.dob?yr-+mb.dob.slice(0,4):0;
    return {kind,mb,h1:"जन्मदिन की",h2:"हार्दिक शुभकामनाएं",name:mb.name||e.name,
      line:e.type==="Tithi Birthday"?`तिथि अनुसार · ${e.sub}`:(n>0?`${n}वां जन्मदिन`:""),
      date:fmtDate(e.iso),msg:"Aap sada khush rahein, swasth rahein aur jeevan mein khoob tarakki karein!",from:`शुभेच्छु – ${fam}`};
  }
  if(kind==="ann"){
    const n=mb.anniversary?yr-+mb.anniversary.slice(0,4):0;
    const nm2=sp?sp.name:(mb.spouse||"");
    return {kind,mb,sp,h1:"शादी की सालगिरह",h2:"मुबारक हो",name:[(mb.name||"").split(" ")[0],(nm2||"").split(" ")[0]].filter(Boolean).join(" & "),
      line:n>0?`${n} साल का साथ`:"",date:fmtDate(e.iso),msg:"Aapki jodi sada salamat rahe, pyaar aur khushiyan yun hi badhti rahein!",from:`शुभेच्छु – ${fam}`};
  }
  return {kind,mb,h1:"भावपूर्ण",h2:"श्रद्धांजलि",name:"स्व. "+(mb.name||e.name),
    line:e.type==="Shraddh"?`श्राद्ध · पितृ पक्ष · ${e.sub.replace(/^Pitru Paksha – /,"")}`:e.type==="Punyatithi (tithi)"?`पुण्यतिथि · ${e.sub}`:`पुण्यतिथि${e.sub?` · ${e.sub}`:""}`,
    date:fmtDate(e.iso),msg:"Aapki yaadein, sanskaar aur aashirwad sada hamare saath rahenge.",from:`– ${famM}`};
}
async function drawPoster(e,themeIdx,msg){
  const W=1080,H=1350,TOP=200; const c=document.createElement("canvas");c.width=W;c.height=H+TOP;const ctx=c.getContext("2d");
  const P=posterInfo(e); const th=THEMES[P.kind][themeIdx%3]; const R=rng(hashStr(e.id+e.type+themeIdx));
  try{ await Promise.all([document.fonts.load('400 90px "Rozha One"',"जन्मदिन"),document.fonts.load('700 60px "Mukta"',"शुभ Ab"),document.fonts.load('600 40px "Mukta"',"Ab")]); }catch(x){}
  await drawDevBand(ctx,W,TOP,th); ctx.translate(0,TOP);
  const g=ctx.createLinearGradient(0,0,W*.4,H);g.addColorStop(0,th.bg[0]);g.addColorStop(1,th.bg[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  // decorations
  if(P.kind==="bday"){
    for(let i=0;i<260;i++){ctx.save();ctx.globalAlpha=.85;ctx.fillStyle=th.deco[i%th.deco.length];const x=R()*W,y=R()*H;
      if(x>110&&x<970&&y>40){ctx.restore();continue}
      ctx.translate(x,y);ctx.rotate(R()*6.28);if(i%3)ctx.fillRect(-9,-4,18,8);else{ctx.beginPath();ctx.arc(0,0,7,0,6.28);ctx.fill()}ctx.restore();}
    [[95,470,th.deco[0]],[175,410,th.deco[1]],[905,430,th.deco[3]],[985,500,th.deco[2]]].forEach(([x,y,col])=>{ctx.strokeStyle="rgba(0,0,0,.25)";ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y+58);ctx.quadraticCurveTo(x+15,y+130,x-5,y+200);ctx.stroke();
      const bg=ctx.createRadialGradient(x-14,y-18,6,x,y,60);bg.addColorStop(0,"rgba(255,255,255,.85)");bg.addColorStop(.25,col);bg.addColorStop(1,col);ctx.fillStyle=bg;ctx.beginPath();ctx.ellipse(x,y,46,58,0,0,6.28);ctx.fill();});
  } else if(P.kind==="fest"){
    for(let i=0;i<26;i++){const x=20+i*(W-40)/25;ctx.fillStyle=th.deco[i%th.deco.length];ctx.beginPath();ctx.arc(x,22+Math.sin(i)*6,22,0,6.28);ctx.fill();}
    for(let i=0;i<26;i++){const x=20+i*(W-40)/25;ctx.fillStyle=th.deco[(i+2)%th.deco.length];ctx.beginPath();ctx.arc(x,H-22+Math.sin(i)*6,22,0,6.28);ctx.fill();}
    for(let i=0;i<90;i++){const x=R()*W,y=60+R()*(H-120);if(x>110&&x<970)continue;ctx.globalAlpha=.5+R()*.5;ctx.fillStyle=th.deco[i%th.deco.length];ctx.beginPath();ctx.arc(x,y,2+R()*5,0,6.28);ctx.fill();}ctx.globalAlpha=1;
  } else if(P.kind==="ann"){
    for(let i=0;i<26;i++){const x=20+i*(W-40)/25;ctx.fillStyle=th.deco[i%th.deco.length];ctx.beginPath();ctx.arc(x,22+Math.sin(i)*6,22,0,6.28);ctx.fill();ctx.fillStyle="rgba(0,0,0,.12)";ctx.beginPath();ctx.arc(x,22+Math.sin(i)*6,8,0,6.28);ctx.fill();}
    for(let i=0;i<22;i++){const x=R()*W,y=120+R()*(H-200);if(x>110&&x<970)continue;ctx.globalAlpha=.35+R()*.4;heart(ctx,x,y,24+R()*34,th.acc);}ctx.globalAlpha=1;
  } else {
    ctx.strokeStyle=th.ring;ctx.lineWidth=3;ctx.strokeRect(36,36,W-72,H-72);ctx.lineWidth=1.5;ctx.strokeRect(50,50,W-100,H-100);
    drawDiya(ctx,150,H-150,.9,th);drawDiya(ctx,W-150,H-150,.9,th);
  }
  ctx.textAlign="center";ctx.textBaseline="alphabetic";
  if(P.kind==="fest"){
    const cx=W/2,cy=560;
    for(let ring=5;ring>=1;ring--){const n=8+ring*4,rr=ring*48;for(let k=0;k<n;k++){const a=k/n*Math.PI*2+(ring%2?0:Math.PI/n);ctx.save();ctx.translate(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr);ctx.rotate(a);ctx.fillStyle=th.deco[(ring+k)%th.deco.length];ctx.globalAlpha=.9;ctx.beginPath();ctx.ellipse(0,0,30,13,0,0,6.28);ctx.fill();ctx.restore();}}
    ctx.globalAlpha=1;ctx.beginPath();ctx.arc(cx,cy,95,0,6.28);ctx.fillStyle=th.bg[0];ctx.fill();ctx.lineWidth=6;ctx.strokeStyle=th.ring;ctx.stroke();
    ctx.font='120px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif';ctx.textAlign="center";ctx.textBaseline="middle";ctx.fillText(P.icon||"🪔",cx,cy+6);
    drawDiya(ctx,150,H-120,.8,th);drawDiya(ctx,W-150,H-120,.8,th);
    ctx.textBaseline="alphabetic";ctx.fillStyle=th.acc;fitFont(ctx,P.h1,'400 {s}px "Rozha One","Mukta",serif',120,W-120,60);ctx.fillText(P.h1,W/2,190);
    ctx.fillStyle=th.ink;ctx.font='400 64px "Rozha One","Mukta",serif';ctx.fillText(P.h2,W/2,890);
    ctx.globalAlpha=.8;ctx.font='500 36px "Mukta",sans-serif';ctx.fillText(P.date,W/2,950);ctx.globalAlpha=1;
    let yy=1030;ctx.font='500 40px "Mukta",sans-serif';wrapLines(ctx,msg??P.msg,W-260).slice(0,3).forEach(l=>{ctx.fillText(l,W/2,yy);yy+=52;});
    ctx.fillStyle=th.acc;ctx.font='400 44px "Rozha One","Mukta",serif';await footerWithLogo(ctx,W,P.from,H-62);
    return c;
  }
  // headline
  ctx.fillStyle=th.ink;ctx.font=`400 ${P.kind==="mem"?78:84}px "Rozha One","Mukta",serif`;ctx.fillText(P.h1,W/2,150);
  ctx.fillStyle=th.acc;ctx.font=`400 ${P.kind==="mem"?96:100}px "Rozha One","Mukta",serif`;ctx.fillText(P.h2,W/2,262);
  // photos
  const gray=P.kind==="mem";
  if(P.kind==="ann"){
    const [a,b]=await Promise.all([loadImgSrc(P.mb.photo),loadImgSrc(P.sp&&P.sp.photo)]);
    circlePhoto(ctx,a,P.mb.name,W/2-150,560,190,th,false);circlePhoto(ctx,b,P.sp?P.sp.name:(P.mb.spouse||"?"),W/2+150,560,190,th,false);
    heart(ctx,W/2,700,70,th.acc);
  } else if(P.kind==="mem"){ circlePhoto(ctx,await loadImgSrc(P.mb.photo),P.mb.name,W/2,545,215,th,true); } else { circlePhoto(ctx,await loadImgSrc(P.mb.photo),P.mb.name,W/2,575,240,th,false); }
  // name
  ctx.fillStyle=th.ink; const ns=fitFont(ctx,P.name,'700 {s}px "Mukta",sans-serif',92,W-160,48); const ny=P.kind==="ann"?880:P.kind==="mem"?870:930; ctx.fillText(P.name,W/2,ny);
  let y=ny+ns*0.75;
  if(P.line){ctx.fillStyle=th.acc;fitFont(ctx,P.line,'600 {s}px "Mukta",sans-serif',48,W-180,30);ctx.fillText(P.line,W/2,y);y+=62;}
  ctx.fillStyle=th.ink;ctx.globalAlpha=.8;ctx.font='500 36px "Mukta",sans-serif';ctx.fillText(P.date,W/2,y);ctx.globalAlpha=1;y+=70;
  ctx.font='500 40px "Mukta",sans-serif';ctx.fillStyle=th.ink;
  wrapLines(ctx,msg??P.msg,W-(P.kind==="mem"?420:220)).slice(0,4).forEach(l=>{ctx.fillText(l,W/2,y);y+=52;});
  ctx.fillStyle=th.acc;ctx.font='400 46px "Rozha One","Mukta",serif';await footerWithLogo(ctx,W,P.from,H-(P.kind==="mem"?95:60));
  return c;
}
const LOGO_SVG=`<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="lgG" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#9b1f45"/><stop offset="1" stop-color="#5a0f24"/></linearGradient></defs><circle cx="32" cy="32" r="31" fill="url(#lgG)"/><circle cx="32" cy="32" r="27.5" fill="none" stroke="#f4c46b" stroke-width="1.4"/><path d="M32 49 C31 43 31 38 32 31 M32 38 C28 35 25 33 22 30 M32 36 C36 33 39 31 42 28 M32 33 C30 29 28 26 27 22 M32 32 C34 28 36 25 37 21" stroke="#f4c46b" stroke-width="2.2" fill="none" stroke-linecap="round"/><g fill="#f4c46b"><circle cx="32" cy="17" r="5.5"/><circle cx="25" cy="20" r="5"/><circle cx="39" cy="20" r="5"/><circle cx="20" cy="27" r="4.5"/><circle cx="44" cy="26" r="4.5"/><circle cx="28" cy="24" r="3.5" opacity=".85"/><circle cx="36" cy="24" r="3.5" opacity=".85"/></g><path d="M22 50 Q32 46 42 50" stroke="#f4c46b" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M32 49 L27 53 M32 49 L37 53 M32 49 L32 54" stroke="#f4c46b" stroke-width="1.6" stroke-linecap="round"/></svg>`;
const KULDEVI_DATA="data:image/jpeg;base64,";
let _logoImg=null;
function logoImg(){ if(_logoImg) return Promise.resolve(_logoImg); return new Promise(res=>{const i=new Image();i.onload=()=>{_logoImg=i;res(i)};i.onerror=()=>res(null);i.src=KULDEVI_DATA;}); }
async function footerWithLogo(ctx,W,text,y){ ctx.textAlign="center"; ctx.fillText(text,W/2,y); }
function imgFrom(src){ return new Promise(res=>{const i=new Image();i.onload=()=>res(i);i.onerror=()=>res(null);i.src=src;}); }
async function drawDevBand(ctx,W,TOP,th){
  const g=ctx.createLinearGradient(0,0,W,0); g.addColorStop(0,"#5a0f24"); g.addColorStop(.5,"#8c1c3a"); g.addColorStop(1,"#5a0f24");
  ctx.fillStyle=g; ctx.fillRect(0,0,W,TOP); ctx.fillStyle="#f4c46b"; ctx.fillRect(0,TOP-8,W,8);
  const [a,b]=await Promise.all([imgFrom(KULDEVI_DATA),imgFrom(typeof KULDEVTA_DATA!=="undefined"?KULDEVTA_DATA:KULDEVI_DATA)]);
  const r=74, cy=TOP/2-4;
  [[a,40+r],[b,W-40-r]].forEach(([im,cx])=>{ ctx.save(); ctx.beginPath(); ctx.arc(cx,cy,r+6,0,Math.PI*2); ctx.fillStyle="#f4c46b"; ctx.shadowColor="rgba(0,0,0,.35)"; ctx.shadowBlur=14; ctx.fill(); ctx.restore();
    if(im){ ctx.save(); ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.clip(); ctx.drawImage(im,cx-r,cy-r,2*r,2*r); ctx.restore(); } });
  ctx.textAlign="center"; ctx.textBaseline="middle"; ctx.fillStyle="#ffe3a3";
  ctx.font='400 50px "Rozha One","Mukta",serif'; ctx.fillText("॥ जय सच्चियाय माता ॥",W/2,cy-34);
  ctx.fillText("॥ जय काला भैरूजी ॥",W/2,cy+36); ctx.textBaseline="alphabetic";
}
let posterState=null;
async function openPoster(e){
  if(!POSTER_TYPES[e.type]){toast("Is date ka poster nahi banta");return}
  const P=posterInfo(e);
  posterState={e,theme:0,msg:P.msg};
  openSheet(`<div class="sheet-head"><h2>Wish poster</h2><button class="x" id="cls">×</button></div>
    <div class="poster-wrap"><img id="posterImg" alt="Poster preview"></div>
    <div class="sec"><h4>🎨 Design</h4><div class="actions" id="themeBtns">${[0,1,2].map(i=>`<button class="swatch${i===0?" on":""}" data-i="${i}" style="background:linear-gradient(135deg,${THEMES[P.kind][i].bg[0]},${THEMES[P.kind][i].bg[1]})" aria-label="Design ${i+1}"></button>`).join("")}</div>
      <label class="f full" style="margin-top:10px">Sandesh (badal sakte ho)<textarea id="posterMsg" maxlength="160">${esc(P.msg)}</textarea></label></div>
    <div class="footer-actions">
      ${waText(e,null)?`<a class="btn plain" href="${esc(waLink(waText(e,Math.round((new Date(e.iso+"T00:00:00")-new Date(new Date().toDateString()))/864e5))))}" target="_blank" rel="noopener">💬 WhatsApp text</a>`:""}
      ${downloads?'<button class="btn" id="posterDl">📤 WhatsApp / Save</button>':""}
    </div>
    <p class="sub" style="font-size:14px;text-align:right">Phone pe dabate hi WhatsApp mein bhejne ka option aayega.</p>`);
  $("#cls").onclick=closeSheet;
  const redraw=async()=>{const c=await drawPoster(posterState.e,posterState.theme,posterState.msg);posterState.canvas=c;const im=$("#posterImg");if(im)im.src=c.toDataURL("image/jpeg",0.85);};
  $("#themeBtns").querySelectorAll(".swatch").forEach(b=>b.onclick=()=>{posterState.theme=+b.dataset.i;$("#themeBtns").querySelectorAll(".swatch").forEach(x=>x.classList.toggle("on",x===b));redraw();});
  let t; $("#posterMsg").oninput=ev=>{posterState.msg=ev.target.value;clearTimeout(t);t=setTimeout(redraw,300);};
  const dl=$("#posterDl"); if(dl) dl.onclick=async()=>{ if(!posterState.canvas) return;
    const blob=await new Promise(r=>posterState.canvas.toBlob(r,"image/jpeg",0.92));
    const nm=(posterState.e.name||"wish").replace(/[^\w\s-]/g,"").trim().replace(/\s+/g,"_");
    try{ await downloads.save({filename:`${nm}_${posterState.e.type.replace(/\W+/g,"_")}.jpg`,data:blob}); toast("Poster save ho gaya ✓"); }catch(x){ if(!x||x.code!=="declined") toast("Save nahi hua"); } };
  redraw();
}
